 await page.getByRole('button',{name:'查看 / 补齐',exact:true}).click();await page.getByRole('heading',{name:'准备本段素材',exact:true}).waitFor();assert.equal(await page.getByRole('tab',{name:'本段素材',exact:true}).getAttribute('aria-selected'),'true');assert(await page.getByRole('button',{name:'播放本段',exact:true}).isDisabled());
 await page.locator('input[accept="image/png,image/jpeg,image/webp,video/*"]').setInputFiles({name:'missing.png',mimeType:'image/png',buffer:Buffer.from(png)});await page.getByRole('button',{name:'播放本段',exact:true}).waitFor({state:'visible'});await page.waitForFunction(()=>!Array.from(document.querySelectorAll('button')).find(b=>b.textContent==='播放本段').disabled);assert(!(await page.getByRole('button',{name:'下一步：完整视频 →',exact:true}).isDisabled()));
 await page.getByRole('tab',{name:'调整画面',exact:true}).click();await page.getByRole('region',{name:'画面设置',exact:true}).waitFor();await page.getByRole('tab',{name:'预览与制作',exact:true}).click();assert.equal(await page.getByRole('region',{name:'画面设置',exact:true}).count(),0);
 await page.getByRole('button',{name:'2 画面安排',exact:true}).click();await page.getByRole('heading',{name:'画面安排',exact:true}).waitFor();assert.equal(await page.locator('iframe,audio').count(),0);assert.equal(await page.getByText('上传配图',{exact:true}).count(),0);assert(await page.getByRole('button',{name:'下一步：录音 →',exact:true}).isVisible());
 await page.getByRole('button',{name:'下一步：录音 →',exact:true}).click();await page.getByText('录音时间已匹配',{exact:true}).waitFor();assert.equal(await page.locator('iframe').count(),0);assert.equal(await page.getByText('添加素材',{exact:true}).count(),0);
 await page.getByRole('button',{name:'下一步：分段制作 →',exact:true}).click();await page.getByRole('button',{name:'播放本段',exact:true}).waitFor();
 await page.setViewportSize({width:390,height:844});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await page.getByRole('button',{name:'预览 / 修改',exact:true}).first().click();await page.waitForFunction(()=>{const r=document.querySelector('.project-preview').getBoundingClientRect();return r.top>=0&&r.top<100});assert((await page.locator('.studio-preview').boundingBox()).height>100);await page.screenshot({path:'/tmp/qa-evidence/production-mobile-preview.png',fullPage:false});
