 assert.deepEqual(errors,[]);assert.deepEqual(consoleErrors,[]);fs.writeFileSync('/tmp/qa-evidence/production-flow-result.json',JSON.stringify({passed:true,tests:['visible segment number selects scene 03','scene title selects without scrolling to footer','card body selects scene','details expand without changing selection','keyboard Enter selects segment','34 segments beside preview above fold','select distant row updates side preview and seek','single segment playback stops before next scene','missing asset opens preparation','upload unlocks preview and next step','stage 2 has no upload or render','stage 3 has only recording and synchronization','step advance scrolls to stage','mobile selection reveals preview','no horizontal overflow','reload retains scene anchors and media','text layer has transparent background'],errors,consoleErrors},null,2));
